const fs = require('fs');
// Parse the feeds file: one URL per line, ignoring blanks and comments.
function parseFeedList(text) {
  return String(text || '')
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter((line) => line && !line.startsWith('#'))
    .filter((line) => /^https?:\/\//i.test(line));
}

const text = fs.readFileSync('/data/config/feeds.txt', 'utf8');
const urls = parseFeedList(text);
if (!urls.length) throw new Error('No feeds configured in config/feeds.txt');
return urls.map((url) => ({ json: { url } }));

const fs = require('fs');
// Turn raw RSS items into a common offer shape and drop already-seen offers.

const MAX_DESCRIPTION_CHARS = 3000;
const SEEN_TTL_DAYS = 30;

function stripHtml(html) {
  return String(html || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

// Canonical id: link without query string, hash or trailing slash.
function offerId(link, title, company) {
  if (link) {
    return String(link).toLowerCase().split('#')[0].split('?')[0].replace(/\/+$/, '');
  }
  return `${String(company || '').toLowerCase()}|${String(title || '').toLowerCase()}`.trim();
}

// Many boards publish titles as "Company: Role".
function splitTitle(rawTitle) {
  const title = String(rawTitle || '').trim();
  const match = title.match(/^([^:]{2,60}):\s+(.+)$/);
  return match ? { company: match[1].trim(), title: match[2].trim() } : { company: '', title };
}

function normalizeOffer(raw, source) {
  const parts = splitTitle(raw.title);
  const company = String(raw.company || raw.creator || parts.company || '').trim();
  const title = parts.title;
  const link = String(raw.link || raw.guid || '').trim();
  const description = stripHtml(raw.content || raw['content:encoded'] || raw.contentSnippet || raw.description)
    .slice(0, MAX_DESCRIPTION_CHARS);
  const location = String(raw.location || raw.region || '').trim();
  return {
    id: offerId(link, title, company),
    title,
    company,
    location,
    link,
    description,
    source: source || '',
    publishedAt: raw.isoDate || raw.pubDate || '',
  };
}

// Returns fresh offers and the updated seen map ({ id: epochMs }), pruning old entries.
function dedupeOffers(offers, seen, nowMs, maxOffers) {
  const ttlMs = SEEN_TTL_DAYS * 24 * 60 * 60 * 1000;
  const nextSeen = {};
  for (const [id, ts] of Object.entries(seen || {})) {
    if (nowMs - ts < ttlMs) nextSeen[id] = ts;
  }
  const fresh = [];
  for (const offer of offers) {
    if (!offer.id || !offer.title || nextSeen[offer.id]) continue;
    if (fresh.length >= maxOffers) break;
    nextSeen[offer.id] = nowMs;
    fresh.push(offer);
  }
  return { fresh, seen: nextSeen };
}

// Build the Claude request for an offer and parse its structured answer.

const MAX_TOKENS = 400;

function fillTemplate(template, profile, offer) {
  const values = {
    PROFILE: profile,
    TITLE: offer.title,
    COMPANY: offer.company || 'Unknown',
    LOCATION: offer.location || 'Unknown',
    LINK: offer.link,
    DESCRIPTION: offer.description || 'No description',
  };
  return String(template).replace(/\{\{(\w+)\}\}/g, (all, key) =>
    Object.prototype.hasOwnProperty.call(values, key) ? String(values[key]) : all);
}

function buildRequestBody(prompt, model) {
  return {
    model,
    max_tokens: MAX_TOKENS,
    temperature: 0,
    messages: [{ role: 'user', content: prompt }],
  };
}

function clampScore(value) {
  const n = Math.round(Number(value));
  if (!Number.isFinite(n)) return 0;
  return Math.max(0, Math.min(100, n));
}

// Accepts the raw Anthropic Messages API response; never throws.
function parseScoreResponse(response) {
  const fallback = (reason) => ({
    score: 0, match_reasons: [], red_flags: [reason], seniority_fit: 'unknown', remote_ok: false, error: true,
  });
  if (!response || response.error) {
    return fallback(`API error: ${response && response.error ? JSON.stringify(response.error).slice(0, 200) : 'empty response'}`);
  }
  const block = Array.isArray(response.content) ? response.content.find((c) => c.type === 'text') : null;
  if (!block) return fallback('No text in model response');
  const text = block.text.trim();
  const jsonText = (text.match(/\{[\s\S]*\}/) || [''])[0];
  let data;
  try {
    data = JSON.parse(jsonText);
  } catch (e) {
    return fallback('Model response was not valid JSON');
  }
  const list = (v) => (Array.isArray(v) ? v.map(String).slice(0, 3) : []);
  return {
    score: clampScore(data.score),
    match_reasons: list(data.match_reasons),
    red_flags: list(data.red_flags),
    seniority_fit: ['under', 'fit', 'over'].includes(data.seniority_fit) ? data.seniority_fit : 'unknown',
    remote_ok: data.remote_ok === true,
    error: false,
  };
}

function hostOf(link) {
  const match = String(link || '').match(/^https?:\/\/([^/]+)/i);
  return match ? match[1] : '';
}

const model = $env.JOBSCOUT_MODEL || 'claude-haiku-4-5-20251001';
const maxOffers = parseInt($env.JOBSCOUT_MAX_OFFERS || '40', 10);
const profile = fs.readFileSync('/data/config/profile.md', 'utf8');
const template = fs.readFileSync('/data/prompts/score-offer.md', 'utf8').replace(/^<!--[\s\S]*?-->\s*/, '');

const raw = $input.all().map((i) => i.json).filter((j) => j && !j.error && (j.title || j.link));
const offers = raw.map((r) => normalizeOffer(r, hostOf(r.link)));

const staticData = $getWorkflowStaticData('global');
const { fresh, seen } = dedupeOffers(offers, staticData.seen || {}, Date.now(), maxOffers);
staticData.seen = seen;

return fresh.map((offer) => ({
  json: { offer, requestBody: buildRequestBody(fillTemplate(template, profile, offer), model) },
}));

